test('eight units at 5.00 discounts only the six paid units', function () {
  var result = code.priceLine({ sku: 'A', units: 8, unitPrice: 5.00 });
  assert.equal(result.normalPrice, 40.00);
  assert.equal(result.freeUnits, 2);
  assert.equal(result.paidUnits, 6);
  assert.equal(result.lineTotal, 27.00);
});

test('three units under four gets only the 10 percent discount', function () {
  var result = code.priceLine({ sku: 'A', units: 3, unitPrice: 5.00 });
  assert.equal(result.freeUnits, 0);
  assert.equal(result.paidUnits, 3);
  assert.equal(result.lineTotal, 13.50);
});

test('seven units leaves leftover paid units after one free set', function () {
  var result = code.priceLine({ sku: 'A', units: 7, unitPrice: 5.00 });
  assert.equal(result.freeUnits, 1);
  assert.equal(result.paidUnits, 6);
  assert.equal(result.lineTotal, 27.00);
});

test('zero units returns a zero line total', function () {
  var result = code.priceLine({ sku: 'A', units: 0, unitPrice: 5.00 });
  assert.equal(result.freeUnits, 0);
  assert.equal(result.paidUnits, 0);
  assert.equal(result.lineTotal, 0.00);
});

test('negative units is rejected and returns no total', function () {
  assert.throws(function () {
    code.priceLine({ sku: 'A', units: -1, unitPrice: 5.00 });
  }, /^invalid field: units$/);
});

test('unit price one step below zero is rejected and returns no total', function () {
  assert.throws(function () {
    code.priceLine({ sku: 'A', units: 1, unitPrice: -0.01 });
  }, /^invalid field: unitPrice$/);
});

test('one unit at 0.05 rounds half up to 0.05', function () {
  var result = code.priceLine({ sku: 'A', units: 1, unitPrice: 0.05 });
  assert.equal(result.freeUnits, 0);
  assert.equal(result.paidUnits, 1);
  assert.equal(result.lineTotal, 0.05);
});

test('free units start at exactly four units', function () {
  var result = code.priceLine({ sku: 'A', units: 4, unitPrice: 1.00 });
  assert.equal(result.freeUnits, 1);
  assert.equal(result.paidUnits, 3);
  assert.equal(result.lineTotal, 2.70);
});

test('one unit above four still has one free unit', function () {
  var result = code.priceLine({ sku: 'A', units: 5, unitPrice: 5.00 });
  assert.equal(result.freeUnits, 1);
  assert.equal(result.paidUnits, 4);
  assert.equal(result.lineTotal, 18.00);
});

test('one unit above eight has two free units', function () {
  var result = code.priceLine({ sku: 'A', units: 9, unitPrice: 5.00 });
  assert.equal(result.freeUnits, 2);
  assert.equal(result.paidUnits, 7);
  assert.equal(result.lineTotal, 31.50);
});

test('unit price of exactly zero is allowed', function () {
  var result = code.priceLine({ sku: 'A', units: 4, unitPrice: 0 });
  assert.equal(result.freeUnits, 1);
  assert.equal(result.paidUnits, 3);
  assert.equal(result.lineTotal, 0.00);
});

test('line total is rounded once for three units at 0.05', function () {
  var result = code.priceLine({ sku: 'A', units: 3, unitPrice: 0.05 });
  assert.equal(result.lineTotal, 0.14);
});

test('unit price one step below the half up example rounds to 0.04', function () {
  var result = code.priceLine({ sku: 'A', units: 1, unitPrice: 0.04 });
  assert.equal(result.lineTotal, 0.04);
});

test('unit price one step above the half up example rounds to 0.05', function () {
  var result = code.priceLine({ sku: 'A', units: 1, unitPrice: 0.06 });
  assert.equal(result.lineTotal, 0.05);
});

test('smallest positive unit price rounds half up to 0.01', function () {
  var result = code.priceLine({ sku: 'A', units: 1, unitPrice: 0.01 });
  assert.equal(result.lineTotal, 0.01);
});
